+type Sort = { column?: keyof typeof sortFunctions; desc: boolean };
+
+/// Without a sort column, flows are ordered by arrival; `desc` reverses that order.
+function isReversedArrival(sort: Sort): boolean {
+    return !sort.column && sort.desc;
+}
+
+function sortFlows(flows: Flow[], sort: Sort): Flow[] {
+    const sorted = toSorted(flows, makeSort(sort));
+    return isReversedArrival(sort) ? sorted.reverse() : sorted;
+}
+
+/// Insert a newly arrived flow into the view, honoring reversed arrival order.
+function insertNewViewItem(
+    view: Flow[],
+    viewIndex: Map<string, number>,
+    flow: Flow,
+    sort: Sort,
+) {
+    if (isReversedArrival(sort)) {
+        const newView = [flow, ...view];
+        return { view: newView, _viewIndex: buildIndex(newView) };
+    }
+    return insertViewItem(view, viewIndex, flow, makeSort(sort));
+}
